async function createSession(sessionId, userId, data) {
  const key = `session:${sessionId}`;
  await redis.hSet(key, {
    userId,
    createdAt: Date.now(),
    lastActive: Date.now(),
    ip: data.ip,
    userAgent: data.userAgent,
  });
  await redis.expire(key, 86400);  // 24-hour session
}

async function touchSession(sessionId) {
  // Update just the lastActive field — no full read/write
  const key = `session:${sessionId}`;
  await redis.hSet(key, 'lastActive', Date.now());
  await redis.expire(key, 86400);  // extend TTL
}

async function getSessionUser(sessionId) {
  // Fetch only what you need
  return redis.hGet(`session:${sessionId}`, 'userId');
}
